import os
import string
from string import split

ip = [int(i) for i in input().split()]
n = ip[0]
k = ip[1]

ipN = [int(i) for i in input().split()]
ipK = [int(i) for i in input().split()]


for k1 in range(0,k):
	flag = 0
	for n1 in range(0,n):
		for i in range(0,100):
			if(((360*i) + ipK[k1]) % ipN[n1] == 0):
				flag = 1
				break
	if (flag == 1):
		print("YES")
	else:
		print("NO")
